import { create } from 'zustand';

export type NotifyType = 'success' | 'error' | 'info';

export interface NotificationItem {
  id: number;
  type: NotifyType;
  title: string;
  message: string;
  createdAt: string;
  read: boolean;
  href?: string;
}

interface NotificationsState {
  notifications: NotificationItem[];
  toastIds: number[];
  notify: (type: NotifyType, title: string, message: string, options?: { href?: string }) => void;
  dismissToast: (id: number) => void;
  dismissAllToasts: () => void;
  markAsRead: (id: number) => void;
  markAllAsRead: () => void;
}

export const useNotificationsStore = create<NotificationsState>((set, get) => ({
  notifications: [],
  toastIds: [],

  notify: (type, title, message, options) => {
    const id = Date.now() + Math.floor(Math.random() * 1000);
    const maxVisibleToasts = 5;
    const toastLifetime = 4000;

    set((state) => ({
      notifications: [
        {
          id,
          type,
          title,
          message,
          createdAt: new Date().toISOString(),
          read: false,
          href: options?.href,
        },
        ...state.notifications,
      ],
      toastIds: [id, ...state.toastIds].slice(0, maxVisibleToasts),
    }));

    setTimeout(() => {
      set((state) => ({
        toastIds: state.toastIds.filter((toastId) => toastId !== id),
      }));
    }, toastLifetime);
  },

  dismissToast: (id) => {
    set((state) => ({
      toastIds: state.toastIds.filter((toastId) => toastId !== id),
      notifications: state.notifications.map((item) =>
        item.id === id ? { ...item, read: true } : item,
      ),
    }));
  },

  dismissAllToasts: () => {
    set((state) => ({
      toastIds: [],
      notifications: state.notifications.map((item) => ({ ...item, read: true })),
    }));
  },

  markAsRead: (id) => {
    set((state) => ({
      notifications: state.notifications.map((item) =>
        item.id === id ? { ...item, read: true } : item,
      ),
    }));
  },

  markAllAsRead: () => {
    set((state) => ({
      notifications: state.notifications.map((item) => ({ ...item, read: true })),
    }));
  },
}));

export const useNotifications = () => {
  const store = useNotificationsStore();
  return {
    notify: store.notify,
    notifications: store.notifications,
    unreadCount: store.notifications.filter((n) => !n.read).length,
    markAsRead: store.markAsRead,
    markAllAsRead: store.markAllAsRead,
  };
};
